"""
    Sum a list of numbers, reporting progress at each step.
    """
def progress_reporting_sum(numbers: Any, progress: Any) -> object {
    count = len(numbers);
    total = 0;
    for (i, number) in enumerate(numbers) {
        progress((i, count));
        total += number;
    }
    progress((count, count));
    return total;
}

"""1-D Cauchy. See http://en.wikipedia.org/wiki/Cauchy_distribution"""
def cauchy(x0: Any, gx: Any, x: Any) -> object {
    gx2 = gx * gx;
    return (gx2 / (((x - x0) ** 2) + gx2));
}

