"""Print the Fibonacci series up to n."""
def fib(n: Any) -> object {
    (a, b) = (0, 1);
    c = [];
    while (b < n) {
        c.append(b);
        (a, b) = (b, (a + b));
    }
    return c;
}

"""
    Courtesy of http://stackoverflow.com/questions/1549641/how-to-capitalize-the-first-letter-of-each-word-in-a-string-python
    :param line:
    :return:
    """
def capitalize(line: Any) -> object {
    return ' '.join((s[0].upper() + s[1:]) for s in line.split(' '));
}

"""
    derivative of d(y/r)/dx
    equivalent to second order derivatives dr_dxy

    :param x:
    :param y:
    :return:
    """
def d_y_diffr_dx(x: Any, y: Any) -> object {
    return ((-x * y) / (((x ** 2) + (y ** 2)) ** (3 / 2.0)));
}
